<?php
declare(strict_types=1);namespace App\Services\Hrd;use App\Contracts\FaceRecognitionService;use App\Models\{Personnel,PersonnelFaceProfile,User};use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{DB,Storage};
class PersonnelFaceEnrollmentService{public function __construct(private FaceRecognitionService$faces){} /** @param array<string,UploadedFile> $samples */public function enroll(Personnel$p,array$samples,User$actor):PersonnelFaceProfile{$encoded=[];foreach(['front','left','right']as$pose){$encoded[$pose]=$this->faces->encode($samples[$pose]);}return DB::transaction(function()use($p,$samples,$encoded,$actor){$old=$p->faceProfile()->with('samples')->first();$paths=[];try{foreach($samples as$pose=>$file)$paths[$pose]=$file->store("personnel-faces/{$p->id}/".now()->format('YmdHis'),'local');$profile=PersonnelFaceProfile::updateOrCreate(['personnel_id'=>$p->id],['provider'=>$this->faces->provider(),'model_name'=>$encoded['front']['model'],'model_version'=>$encoded['front']['model_version'],'status'=>'active','primary_reference_photo_path'=>$paths['front'],'registered_at'=>now(),'registered_by'=>$actor->id]);$oldPaths=$old?->samples->pluck('photo_path')->push($old->primary_reference_photo_path)->filter()->all()??[];$profile->samples()->delete();foreach($encoded as$pose=>$result)$profile->samples()->create(['photo_path'=>$paths[$pose],'pose'=>$pose,'quality_score'=>$result['quality_score'],'embedding'=>$result['embedding'],'embedding_version'=>$result['model_version']]);Storage::disk('local')->delete($oldPaths);activity('hrd')->causedBy($actor)->performedOn($p)->log($old?'Mendaftarkan ulang wajah personalia.':'Mendaftarkan wajah personalia.');return$profile;}catch(\Throwable$e){Storage::disk('local')->delete($paths);throw$e;}},3);}public function delete(Personnel$p,User$actor):void{DB::transaction(function()use($p,$actor){$profile=$p->faceProfile()->with('samples')->firstOrFail();$paths=$profile->samples->pluck('photo_path')->push($profile->primary_reference_photo_path)->filter()->all();$profile->update(['status'=>'inactive']);$profile->samples()->delete();Storage::disk('local')->delete($paths);activity('hrd')->causedBy($actor)->performedOn($p)->log('Menghapus data wajah personalia.');});}}
